/**
 * @description : Nav Bar (Redesigned as modern vertical left sidebar)
 * @author : Bala krishna
 * @date : 16-01-2023
 */

import React, { useContext, useEffect, useState } from 'react';
import {
  FaUniversity,
  FaCalendarAlt,
  FaBuilding,
  FaChalkboardTeacher,
  FaInfoCircle,
  FaUserTie,
  FaClipboardList,
  FaBookOpen,
  FaMoneyBill,
  FaBook,
  FaTshirt,
  FaBus,
  FaUserFriends,
  FaUserGraduate,
  FaUserCheck,
  FaChartBar,
  FaFileAlt,
  FaCog,
  FaUser,
  FaUserShield,
  FaRegLightbulb,
  FaChevronDown,
  FaChevronRight,
  FaHeadset,
} from 'react-icons/fa';

import { IoNotificationsSharp } from 'react-icons/io5';
import { HiInformationCircle } from 'react-icons/hi2';
import { PiUploadSimpleBold } from 'react-icons/pi';
import { RiDashboardFill } from 'react-icons/ri';

import { Link, useLocation } from 'react-router-dom';

import { AuthContext } from '../../App';
import { isExactMatch } from '../../services/commonUtills/FormValidations';

const getActiveNavModule = (pathname) => {
  if (!pathname || pathname === '/') {
    return 'dashboard';
  }

  if (pathname.startsWith('/dashboard')) {
    return 'dashboard';
  }

  return '';
};

const NavBar = () => {
  const location = useLocation();
  const { stateAuth } = useContext(AuthContext);

  const [activeModule, setActiveModule] = useState(
    getActiveNavModule(location.pathname)
  );

  const isSublinkActive = (path) => {
    return location.pathname === path;
  };

  useEffect(() => {
    setActiveModule(getActiveNavModule(location.pathname));
  }, [location.pathname]);

  return (
    <ul className="sidebar-menu">

      {/* Dashboard Link */}
      {isExactMatch(stateAuth.user.cds, 'D_H_B') && (
        <li
          className={`sidebar-menu-item ${
            activeModule === 'dashboard' ? 'active' : ''
          }`}
        >
          <Link to="/dashboard" className="sidebar-menu-link">
            <RiDashboardFill className="menu-icon" />
            <span>Dashboard</span>
          </Link>
        </li>
      )}

      {/* Home Work Link */}
      {isExactMatch(stateAuth.user.cds, 'H_W_C') && (
        <li
          className={`sidebar-menu-item ${
            isSublinkActive('/dashboard/Home-work') ? 'active-sub' : ''
          }`}
        >
          <Link
            to="/dashboard/Home-work"
            className="sidebar-menu-link sub"
          >
            <HiInformationCircle className="menu-icon" />
            <span>Home work</span>
          </Link>
        </li>
      )}

    </ul>
  );
};

export default NavBar;
